function rakUpgradeCmsSeoContent(array &$content): bool {
    if (empty($content)) {
        return false;
    }

    $changed = false;
    $schemaVer = (int)($content['seoSchemaVersion'] ?? 0);

    // Ensure home banner eyebrow & subtitle have strong Lebanon digital marketing defaults if empty
    if (isset($content['banners']['home']) && is_array($content['banners']['home'])) {
        if (empty($content['banners']['home']['eyebrow'])) {
            $content['banners']['home']['eyebrow'] = 'Digital Marketing Agency in Lebanon • Beirut & Toronto';
            $changed = true;
        }
        if (empty($content['banners']['home']['subtitle'])) {
            $content['banners']['home']['subtitle'] = 'Full-service digital marketing agency in Lebanon serving Beirut, MENA, GCC, and global brands across social media marketing, Meta & Google paid ads, SEO, branding, web development, and media production.';
            $changed = true;
        }
        if (($content['banners']['home']['primaryCtaLabel'] ?? '') === 'Learn More') {
            $content['banners']['home']['primaryCtaLabel'] = 'Explore Capabilities';
            $changed = true;
        }
    }

    // One-time seed of the 2 Lebanon digital marketing authority blog posts into live CMS storage
    if ($schemaVer < 2) {
        if (!isset($content['blogPosts']) || !is_array($content['blogPosts'])) {
            $content['blogPosts'] = [];
        }
        $existingIds = [];
        foreach ($content['blogPosts'] as $bp) {
            if (is_array($bp) && !empty($bp['id'])) {
                $existingIds[strtolower(trim((string)$bp['id']))] = true;
            }
        }
        foreach (rakGetSeedLebanonBlogPosts() as $seedPost) {
            $seedId = strtolower($seedPost['id']);
            if (!isset($existingIds[$seedId])) {
                $content['blogPosts'][] = $seedPost;
                $changed = true;
            }
        }
        if (empty($content['faqs']) || !is_array($content['faqs'])) {
            $content['faqs'] = rakGetDefaultLebanonFaqs();
            $changed = true;
        }
        $content['seoSchemaVersion'] = 2;
        $changed = true;
    }

    return $changed;
}

